// =====================================================================
// EVERWAKE CLINIC — Tool: manage_booking · NODE: Read Args
// What the agent sent → the SQL call. details arrives as an object (n8n
// "json" type) or as text; it goes to the database base64-encoded, so
// quotes in Arabic text can never break the query.
// =====================================================================
// ---- shared: basics ----------------------------------------------------
const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const arr = (v) => Array.isArray(v) ? v : (v ? [v] : []);
const str = (v) => String(v == null ? '' : v).trim();
const num = (v, d = 0) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const money = (n) => Math.round(num(n) * 100) / 100;
const fmt = (n) => String(money(n));
const b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');
const parseJson = (v, d) => {
  if (v && typeof v === 'object') return v;
  try { const x = JSON.parse(v); return x == null ? d : x; } catch (e) { return d; }
};
// a Postgres node returns { r: <jsonb> }; a missing row returns {}
const row = (j) => obj(parseJson(obj(j).r, {}));
// an Egyptian number as people write it: 201001234567 → 01001234567
const localPhone = (p) => str(p).replace(/^\+?20(1\d{9})$/, '0$1');
const t = $input.first().json;
let details = t.details;
if (typeof details === 'string') details = parseJson(details, {});
details = obj(details);
delete details.none;
return [{ json: { tenant_id: str(t.tenant_id), wa_id: str(t.wa_id), action: str(t.action).toLowerCase().trim() || 'status',
                  details_b64: Buffer.from(JSON.stringify(details), 'utf8').toString('base64') } }];

// =====================================================================
// EVERWAKE CLINIC — Tool: manage_booking · NODE: Return To Agent
// The database's answer, as the agent reads it. Options keep their
// number and their label (the true day and time) and lose the ids.
// =====================================================================
// ---- shared: basics ----------------------------------------------------
const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const arr = (v) => Array.isArray(v) ? v : (v ? [v] : []);
const str = (v) => String(v == null ? '' : v).trim();
const num = (v, d = 0) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const money = (n) => Math.round(num(n) * 100) / 100;
const fmt = (n) => String(money(n));
const b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');
const parseJson = (v, d) => {
  if (v && typeof v === 'object') return v;
  try { const x = JSON.parse(v); return x == null ? d : x; } catch (e) { return d; }
};
// a Postgres node returns { r: <jsonb> }; a missing row returns {}
const row = (j) => obj(parseJson(obj(j).r, {}));
// an Egyptian number as people write it: 201001234567 → 01001234567
const localPhone = (p) => str(p).replace(/^\+?20(1\d{9})$/, '0$1');
const r = row($input.first().json);
const trimSlot = (o) => { const x = obj(o); return { option: x.option, label: x.label_ar, label_en: x.label_en, doctor: x.doctor, location: x.location,
                                                    kind: x.kind, queue_no: x.queue_no, date: x.date, time: x.time, band: x.band }; };
const out = { ...r };
if (Array.isArray(r.options)) out.options = r.options.map(trimSlot);
for (const p of arr(out.problems)) if (Array.isArray(p.suggested)) p.suggested = p.suggested.slice(0, 3).map(trimSlot);
if (Array.isArray(r.suggested)) out.suggested = r.suggested.slice(0, 3).map(trimSlot);
return [{ json: { response: JSON.stringify(out) } }];
